import{_ as t,c as n,j as e,a as l,o as r}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第一百八十五章 对亲人说谎","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/185第一百八十五章 对亲人说谎.md","filePath":"meditation/巴利文大藏经/185第一百八十五章 对亲人说谎.md"}'),o={name:"meditation/巴利文大藏经/185第一百八十五章 对亲人说谎.md"};function _(s,a,i,d,p,c){return r(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第一百八十五章-对亲人说谎",tabindex:"-1"},[l("第一百八十五章 对亲人说谎 "),e("a",{class:"header-anchor",href:"#第一百八十五章-对亲人说谎","aria-label":'Permalink to "第一百八十五章 对亲人说谎"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部17相应38-43经/父亲经等六则(利得恭敬相应/因缘篇/如来记说)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望，这些是让人内心颤抖恐怖的，这些是让人内心激烈搅动的，这些是让人内心暴躁不安的，这些是修行人内心达到清净安稳的障碍，这些是修行人内心挣脱束缚捆绑的阻碍。",-1),e("p",null,"弟子们，有一位修行人，他过去待人非常的真诚，修行也非常的精进，他不会对自己的父亲、兄弟、姐妹、妻子、儿子、女儿说假话，他不会欺骗自己的父亲、兄弟、姐妹、妻子、儿子、女儿。可是这个修行人现在却为了获得世间人丰厚的供养，获得富贵舒适的生活，获得世间人虔诚的尊敬、恭敬，获得家喻户晓的名誉声望而故意的说谎话骗人，甚至于他连自己的父亲、兄弟、姐妹、妻子、儿子、女儿都欺骗，他对自己的父亲、兄弟、姐妹、妻子、儿子、女儿都说假话。他已经被贪欲所控制，他已经成为了贪欲的奴役，他已经陷入贪欲的沼泽之中无法自拔。",-1),e("p",null,"弟子们，世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望就是这样的让人内心颤抖恐怖，就是这样的让人内心激烈搅动，就是这样的让人内心暴躁不安。",-1),e("p",null,"世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望是修行人内心达到清净安稳的障碍，是修行人内心挣脱束缚捆绑的阻碍。弟子们，因此，你们应该这样去修行：「我们要舍离、放弃已经获得的丰厚供养，我们要舍离、放弃已经获得的富贵舒适的生活，我们要舍离、放弃已经获得的世间人虔诚的尊敬、恭敬，我们要舍离、放弃已经获得的家喻户晓的名誉声望。而且我们不要执着和挂念这些已经获得的丰厚供养，不要执着和挂念这些已经获得的富贵舒适的生活，不要执着和挂念这些已经获得的世间人虔诚的尊敬、恭敬，不要执着和挂念这些已经获得的家喻户晓的名誉声望。我们不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望扰乱我们的内心；不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望让我们胡思乱想、内心散乱。」弟子们，你们就应该这样的去修行。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(o,[["render",_]]);export{u as __pageData,f as default};
